/* ============================================================
   ONE module declaration, for one specifier, for one guard.

   `state/catalogue.designer.test.ts` reads the SOURCE TEXT of the
   catalogue commands to prove that nothing in the column acts still
   claims this app has no undo — the old designer's four confirm
   sheets said it, all four were false, and prose is exactly what
   drifts back. A behavioural test cannot see a sentence.

   Vite serves `?raw`; TypeScript needs telling. Declared one
   specifier at a time, the precedent `curation.raw.d.ts` set, and
   for its reason: a wildcard is a quiet way to import anything as a
   string.
   ============================================================ */

declare module '@/domain/catalogue/commands.ts?raw' {
  const source: string
  export default source
}

declare module '@/domain/catalogue/columnFacts.ts?raw' {
  const source: string
  export default source
}
